import Link from "next/link";
import { Crown } from "lucide-react";
export function PremiumNotice({
  feature,
  id,
}: {
  feature: string;
  id: string;
}) {
  return (
    <div
      id={id}
      className={`flex items-start gap-2.5 mt-3.5 py-2.5 px-3.5 rounded-[var(--appearance-radius,_12px)] [background:var(--premium-notice-background)] [border:1px_solid_var(--premium-notice-border)] text-[var(--premium-notice-text)] text-[13px] leading-[1.65]`}
    >
      <Crown size={16} className="premium-icon mt-1" aria-hidden="true" />
      <p>
        {feature} · Premium required.{" "}
        <Link
          className="relative isolate inline-block overflow-hidden align-middle text-[var(--settings-purple)] font-semibold no-underline wrap-anywhere css-hover:underline"
          href="/usage"
        >
          View Premium plan
        </Link>{" "}
        · Checkout is available in Usage when configured.
      </p>
    </div>
  );
}
